head.b:skin:
/* Tema Blue Converter - QR Studio PRO */
:root {
  --bg: #0f172a; --sup: #1e293b; --borda: #334155; --borda-hover: #3b82f6;
  --texto: #f8fafc; --texto-2: #94a3b8; --acento: #2563eb; --acento-hover: #1d4ed8;
  --r: 12px; --sombra: 0 4px 6px -1px rgba(0,0,0,0.1);
}
*,*::before,*::after { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--texto); font: 16px/1.55 system-ui, sans-serif; min-height: 100vh; display: flex; flex-direction: column; }
.wrap { width: 100%; max-width: 900px; margin: 0 auto; padding: 0 20px 40px; }

.hero { text-align: center; padding: 40px 0 20px; }
.hero h1 { margin: 0; font-size: 2.2rem; font-weight: 700; color: #fff; }
.hero p { color: var(--texto-2); max-width: 650px; margin: 10px auto 0; font-size: 1.05rem; }

/* Abas */
.abas { display: flex; justify-content: center; gap: 10px; margin-bottom: 30px; }
.btn-aba { background: #1e293b; border: 1px solid var(--borda); color: var(--texto-2); padding: 10px 24px; border-radius: 8px; font-weight: 600; cursor: pointer; transition: 0.15s; }
.btn-aba.ativo { background: var(--acento); color: #fff; border-color: var(--acento); }

/* Layout Grid 2 Colunas */
.painel-ferramenta { display: none; background: #1e293b; border-radius: var(--r); padding: 25px; border: 1px solid var(--borda); box-shadow: var(--sombra); }
.painel-ferramenta.ativo { display: grid; gap: 30px; grid-template-columns: 1fr; }
@media (min-width: 768px) { .painel-ferramenta.ativo.split { grid-template-columns: 1fr 1fr; } }

/* Formulários */
.secao-titulo { font-size: 1.1rem; border-bottom: 1px solid var(--borda); padding-bottom: 8px; margin-bottom: 15px; color: #fff; }
.grupo-form { display: flex; flex-direction: column; gap: 6px; margin-bottom: 12px; }
.grupo-inline { display: flex; gap: 15px; margin-bottom: 12px; }
label { font-size: 0.9rem; font-weight: 600; color: var(--texto-2); }
input, select, textarea { width: 100%; background: #0f172a; border: 1px solid var(--borda); border-radius: 8px; padding: 12px; color: #fff; font-size: 0.95rem; outline: none; }
input:focus, select:focus, textarea:focus { border-color: var(--borda-hover); }

input[type="color"] { padding: 2px 5px; height: 42px; cursor: pointer; }

/* Campos Dinâmicos */
.campo-dinamico { display: none; }
.campo-dinamico.ativo { display: block; }

.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 0 24px; font-weight: 600; cursor: pointer; border-radius: 8px; border: none; transition: 0.15s; color: #fff; background: var(--acento); width: 100%; }
.btn:hover { background: var(--acento-hover); }

/* Display do QR */
.qr-coluna { display: flex; flex-direction: column; align-items: center; justify-content: flex-start; background: #0f172a; padding: 20px; border-radius: 8px; border: 1px dashed var(--borda); text-align: center; }
#qrcode-canvas { background: transparent; border-radius: 6px; margin-bottom: 15px; max-width: 100%; height: auto; box-shadow: 0 4px 10px rgba(0,0,0,0.3); }

/* Leitor */
.leitor-box { text-align: center; }
video { width: 100%; max-width: 400px; border-radius: 8px; background: #000; display: none; margin: 0 auto 15px; }
video.ativo { display: block; }

.aviso { position: fixed; bottom: 30px; left: 50%; transform: translate(-50%, 20px); background: #334155; color: #fff; padding: 12px 24px; border-radius: 99px; opacity: 0; pointer-events: none; transition: 0.2s; z-index: 50; }
.aviso.ver { opacity: 1; transform: translate(-50%, 0); }
.main-section { display: none; }

b:if.script:
//
document.addEventListener('DOMContentLoaded', function() {
  const aviso = document.getElementById('aviso');
  function showToast(msg) {
    aviso.textContent = msg;
    aviso.className = 'aviso ver';
    setTimeout(() => aviso.classList.remove('ver'), 3000);
  }

  // --- NAVEGAÇÃO DE ABAS ---
  const tabGerarBtn = document.getElementById('tab-gerar-btn');
  const tabLerBtn = document.getElementById('tab-ler-btn');
  const painelGerar = document.getElementById('painel-gerar');
  const painelLer = document.getElementById('painel-ler');

  tabGerarBtn.addEventListener('click', () => {
    tabGerarBtn.classList.add('ativo'); tabLerBtn.classList.remove('ativo');
    painelGerar.classList.add('ativo'); painelLer.classList.remove('ativo');
    pararCamera();
  });

  tabLerBtn.addEventListener('click', () => {
    tabLerBtn.classList.add('ativo'); tabGerarBtn.classList.remove('ativo');
    painelLer.classList.add('ativo'); painelGerar.classList.remove('ativo');
  });

  // --- LÓGICA DE INTERFACE DINÂMICA ---
  const qrTipo = document.getElementById('qr-tipo');
  const forms = {
    texto: document.getElementById('form-texto'),
    vcard: document.getElementById('form-vcard'),
    email: document.getElementById('form-email'),
    wifi:  document.getElementById('form-wifi')
  };

  qrTipo.addEventListener('change', () => {
    Object.values(forms).forEach(f => f.classList.remove('ativo'));
    forms[qrTipo.value].classList.add('ativo');
    gerarQR();
  });

  // --- COLETA DE DADOS PARA O QR CODE ---
  function getQRData() {
    const tipo = qrTipo.value;
    if (tipo === 'texto') return document.getElementById('in-texto').value.trim() || 'https://torbr.com';

    if (tipo === 'vcard') {
      const n = document.getElementById('vc-nome').value;
      const t = document.getElementById('vc-tel').value;
      const e = document.getElementById('vc-email').value;
      const o = document.getElementById('vc-org').value;
      return `BEGIN:VCARD\nVERSION:3.0\nFN:${n}\nORG:${o}\nTEL:${t}\nEMAIL:${e}\nEND:VCARD`;
    }

    if (tipo === 'email') {
      const p = document.getElementById('em-para').value;
      const a = document.getElementById('em-assunto').value;
      const c = document.getElementById('em-corpo').value;
      return `MATMSG:TO:${p};SUB:${a};BODY:${c};;`;
    }

    if (tipo === 'wifi') {
      const s = document.getElementById('wi-ssid').value;
      const p = document.getElementById('wi-senha').value;
      const t = document.getElementById('wi-tipo').value;
      return `WIFI:S:${s};T:${t};P:${p};;`;
    }
  }

  // --- MOTOR DE GERAÇÃO (CANVAS + LOGO) ---
  const canvas = document.getElementById('qrcode-canvas');
  const corFrente = document.getElementById('qr-cor-frente');
  const corFundo = document.getElementById('qr-cor-fundo');
  const logoInput = document.getElementById('qr-logo-input');
  const btnRemoverLogo = document.getElementById('btn-remover-logo');
  const btnBaixar = document.getElementById('btn-baixar');

  let logoImgObj = null; // Armazena a imagem do logo

  // Atualiza ao digitar ou mudar cor
  const allInputs = document.querySelectorAll('.config-coluna input, .config-coluna textarea, .config-coluna select');
  allInputs.forEach(input => {
    if(input !== logoInput) input.addEventListener('input', gerarQR);
  });

  logoInput.addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(event) {
      logoImgObj = new Image();
      logoImgObj.onload = () => {
        btnRemoverLogo.style.display = 'inline-block';
        gerarQR();
      };
      logoImgObj.src = event.target.result;
    };
    reader.readAsDataURL(file);
  });

  btnRemoverLogo.addEventListener('click', () => {
    logoImgObj = null;
    logoInput.value = '';
    btnRemoverLogo.style.display = 'none';
    gerarQR();
  });

  // Desenha uma célula com cantos arredondados, com fallback para navegadores sem roundRect.
  function desenharCelula(ctx, x, y, w, h, raio) {
    ctx.beginPath();
    if (ctx.roundRect) {
      ctx.roundRect(x, y, w, h, raio);
    } else {
      ctx.rect(x, y, w, h);
    }
    ctx.fill();
  }

  function gerarQR() {
    const dado = getQRData();
    try {
      if (typeof qrcode === 'undefined') {
        throw new Error('Biblioteca do gerador não carregada.');
      }

      // Usa 'H' (High) error correction para suportar logotipos no centro
      const qr = qrcode(0, 'H');
      qr.addData(dado);
      qr.make();

      const ctx = canvas.getContext('2d');
      const moduleCount = qr.getModuleCount();
      const cellSize = 12; // Alta resolução (scale)
      const margin = 24;
      const size = moduleCount * cellSize + margin * 2;

      canvas.width = size;
      canvas.height = size;

      // Fundo
      ctx.fillStyle = corFundo.value;
      ctx.fillRect(0, 0, size, size);

      // Blocos do QR
      ctx.fillStyle = corFrente.value;
      for (let r = 0; r < moduleCount; r++) {
        for (let c = 0; c < moduleCount; c++) {
          if (qr.isDark(r, c)) {
            // Desenho com cantos levemente arredondados para um ar mais moderno
            desenharCelula(ctx, margin + c * cellSize, margin + r * cellSize, cellSize, cellSize, 2);
          }
        }
      }

      // Desenhar o Logo (se existir)
      if (logoImgObj) {
        // Tamanho do logo: ~25% do tamanho total para não quebrar a leitura
        const logoSize = size * 0.25; 
        const logoX = (size - logoSize) / 2;
        const logoY = (size - logoSize) / 2;

        // Fundo branco atrás do logo para contraste
        ctx.fillStyle = corFundo.value;
        desenharCelula(ctx, logoX - 5, logoY - 5, logoSize + 10, logoSize + 10, 8);

        // Imagem do logo
        ctx.drawImage(logoImgObj, logoX, logoY, logoSize, logoSize);
      }
    } catch (e) {
      console.error('Erro ao gerar QR:', e);
      showToast('Erro ao gerar QR Code');
    }
  }

  btnBaixar.addEventListener('click', () => {
    const link = document.createElement('a');
    link.download = 'qrcode_studio.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
    showToast('QR Code baixado em Alta Resolução!');
  });

  // Inicializa a tela pela primeira vez
  gerarQR();


  // --- MOTOR DE LEITURA (jsQR) ---
  const video = document.getElementById('video-webcam');
  const canvasLeitura = document.getElementById('canvas-leitura');
  const btnAtivarCam = document.getElementById('btn-ativar-cam');
  const inputImgQr = document.getElementById('input-img-qr');
  const qrResultadoTxt = document.getElementById('qr-resultado-txt');
  let streamCam = null;
  let animFrame = null;

  btnAtivarCam.addEventListener('click', () => streamCam ? pararCamera() : iniciarCamera());

  function iniciarCamera() {
    navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
      .then(stream => {
        streamCam = stream;
        video.srcObject = stream;
        video.setAttribute('playsinline', true);
        video.play();
        video.classList.add('ativo');
        btnAtivarCam.textContent = 'Desligar Câmara';
        animFrame = requestAnimationFrame(escanearFrame);
      }).catch(err => showToast('Acesso à câmara negado ou não suportado.'));
  }

  function pararCamera() {
    if (streamCam) { streamCam.getTracks().forEach(track => track.stop()); streamCam = null; }
    if (animFrame) cancelAnimationFrame(animFrame);
    video.classList.remove('ativo');
    btnAtivarCam.textContent = 'Ligar Câmara';
  }

  function escanearFrame() {
    if (video.readyState === video.HAVE_ENOUGH_DATA) {
      canvasLeitura.width = video.videoWidth;
      canvasLeitura.height = video.videoHeight;
      const ctx = canvasLeitura.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(video, 0, 0, canvasLeitura.width, canvasLeitura.height);
      const imgData = ctx.getImageData(0, 0, canvasLeitura.width, canvasLeitura.height);

      const codigo = jsQR(imgData.data, imgData.width, imgData.height, { inversionAttempts: 'dontInvert' });
      if (codigo) {
        qrResultadoTxt.value = codigo.data;
        showToast('QR Code lido com sucesso!');
        pararCamera();
        return;
      }
    }
    animFrame = requestAnimationFrame(escanearFrame);
  }

  inputImgQr.addEventListener('change', function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(evt) {
      const img = new Image();
      img.onload = function() {
        canvasLeitura.width = img.width;
        canvasLeitura.height = img.height;
        const ctx = canvasLeitura.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(img, 0, 0);
        const imgData = ctx.getImageData(0, 0, canvasLeitura.width, canvasLeitura.height);

        const codigo = jsQR(imgData.data, imgData.width, imgData.height);
        if (codigo) {
          qrResultadoTxt.value = codigo.data;
          showToast('QR lido a partir da imagem!');
        } else {
          showToast('QR não detetado. Tente uma imagem mais nítida.');
        }
      };
      img.src = evt.target.result;
    };
    reader.readAsDataURL(file);
    this.value = ''; // reseta
  });
});
//
